import React, { useEffect, useState } from 'react';
import ConfirmModal from './ConfirmModal';

function AdminManagementModal({ showId = 'adminManagementModal', adminToken }) {
  const [admins, setAdmins] = useState([]);
  const [name, setName] = useState('');
  const [token, setToken] = useState('');
  const [isOwner, setIsOwner] = useState(false);
  const [loading, setLoading] = useState(false);
  const [confirmShow, setConfirmShow] = useState(false);
  const [confirmTarget, setConfirmTarget] = useState(null);

  const fetchAdmins = () => {
    fetch('/api/admins')
      .then(r => r.json())
      .then(setAdmins)
      .catch(() => setAdmins([]));
  };

  useEffect(() => {
    fetchAdmins();
  }, []);

  const addAdmin = () => {
    if (!name || !token) return alert('الرجاء إدخال اسم و رمز');
    setLoading(true);
    fetch('/api/admins', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...(adminToken ? { 'x-admin-token': adminToken } : {}) },
      body: JSON.stringify({ name, token, isOwner })
    })
      .then(r => {
        if (!r.ok) throw new Error('خطأ');
        return r.json();
      })
      .then(() => {
        setName(''); setToken(''); setIsOwner(false); fetchAdmins();
      })
      .catch(err => alert('لا يمكن إضافة الأدمن: ' + (err.message || 'خطأ')))
      .finally(() => setLoading(false));
  };

  const requestRemoveAdmin = (admin) => {
    setConfirmTarget(admin);
    setConfirmShow(true);
  };

  const removeAdmin = () => {
    if (!confirmTarget) return setConfirmShow(false);
    const id = confirmTarget.id;
    setConfirmShow(false);
    setConfirmTarget(null);
    fetch(`/api/admins/${id}`, {
      method: 'DELETE',
      headers: { ...(adminToken ? { 'x-admin-token': adminToken } : {}) }
    })
      .then(r => {
        if (!r.ok) throw new Error('خطأ');
        fetchAdmins();
      })
      .catch(err => alert('لا يمكن حذف الأدمن: ' + (err.message || 'خطأ')));
  };

  const cancelRemoveAdmin = () => { setConfirmShow(false); setConfirmTarget(null); };

  return (
    <div className="modal fade" id={showId} tabIndex="-1" aria-hidden="true">
      <div className="modal-dialog modal-md modal-dialog-centered">
        <div className="modal-content">
          <div className="modal-header">
            <h5 className="modal-title">إدارة الأدمن</h5>
            <button type="button" className="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
          </div>
          <div className="modal-body">
            <div className="mb-3">
              <label className="form-label">الاسم</label>
              <input className="form-control" value={name} onChange={e => setName(e.target.value)} />
            </div>
            <div className="mb-3">
              <label className="form-label">رمز الأدمن (مفتاح)</label>
              <input className="form-control" value={token} onChange={e => setToken(e.target.value)} />
            </div>
            <div className="form-check mb-3">
              <input className="form-check-input" type="checkbox" checked={isOwner} onChange={e => setIsOwner(e.target.checked)} id="isOwnerCheck" />
              <label className="form-check-label" htmlFor="isOwnerCheck">اجعل هذا الأدمن مالكاً (يمكنه حذف و إدارة الأدمن)</label>
            </div>
            <div className="d-flex justify-content-end mb-3">
              <button className="btn btn-secondary me-2" data-bs-dismiss="modal">إغلاق</button>
              <button className="btn btn-primary" onClick={addAdmin} disabled={loading}>{loading ? 'جارٍ...' : 'إضافة'}</button>
            </div>

            <hr />

            <h6>قائمة الأدمن</h6>
            <ul className="list-group">
              {admins.map(a => (
                <li key={a.id} className="list-group-item d-flex justify-content-between align-items-center">
                  <div>
                    <strong>{a.name}</strong>
                    <div className="small text-muted">{a.token ? a.token : 'مخفي'} {a.isOwner ? '· مالك' : ''}</div>
                  </div>
                  <div>
                    <button className="btn btn-sm btn-danger" onClick={() => requestRemoveAdmin(a)}>حذف</button>
                  </div>
                </li>
              ))}
            </ul>

          </div>
        </div>
      </div>

      <ConfirmModal show={confirmShow} title="تأكيد حذف الأدمن" body={`هل أنت متأكد أنك تريد حذف ${confirmTarget?.name || ''}?`} onConfirm={removeAdmin} onCancel={cancelRemoveAdmin} />
    </div>
  );
}

export default AdminManagementModal;
